<?php
declare(strict_types=1);
$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $e($customer['full_name']) ?> | Triple R Gensan</title><link rel="stylesheet" href="/assets/css/app.css"><script src="/assets/js/customers.js" defer></script></head><body><header class="topbar"><a class="brand" href="/staff">Triple R Gensan</a><nav class="staff-actions"><a href="/customers">Customers</a><a href="/fleet/vehicles">Fleet</a><form method="post" action="/staff/logout"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><button class="button-secondary" type="submit">Sign out</button></form></nav></header><main class="page-shell" data-reveal-url="/customers/reveal" data-csrf="<?= $e($csrfToken) ?>">
<section class="page-heading"><div><p class="eyebrow">Customer profile</p><h1><?= $e($customer['full_name']) ?></h1><p><?= $e(str_replace('_',' ',$customer['customer_type'])) ?><?php if($customer['company_name']):?> · <?= $e($customer['company_name']) ?><?php endif;?> · <?= (int)$customer['is_blacklisted']===1?'Blacklisted':'Eligible for new bookings' ?></p></div><?php if($customer['deleted_at']===null):?><a class="button-link" href="/customers/edit?customer_id=<?= (int)$customer['customer_id'] ?>">Edit profile</a><?php endif;?></section><?php if($notice):?><p class="alert" role="status"><?= $e($notice) ?></p><?php endif;?>
<section class="panel"><div class="panel-heading"><h2>Contact channels</h2></div><?php if($customer['deleted_at']===null):?><form class="form-grid" method="post" action="/customers/contacts/add"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="customer_id" value="<?= (int)$customer['customer_id'] ?>"><label>Type<select name="contact_type"><option value="phone">Phone</option><option value="email">Email</option></select></label><label>Contact value<input name="contact_value" required maxlength="254"></label><label class="check-label"><input type="checkbox" name="is_primary" value="1"> Make primary</label><button type="submit">Add contact</button></form><?php endif;?><div class="table-wrap"><table><thead><tr><th>Type</th><th>Value</th><th>Primary</th><th>Actions</th></tr></thead><tbody><?php foreach($contacts as $contact):?><tr><td><?= $e($contact['contact_type']) ?></td><td><span data-pii-value><?= $e($contact['masked_value']) ?></span> <button type="button" class="button-small" data-reveal-kind="contact" data-record-id="<?= (int)$contact['contact_id'] ?>">Reveal</button></td><td><?= (int)$contact['is_primary']===1?'Yes':'No' ?></td><td><?php if($customer['deleted_at']===null):?><details><summary>Edit</summary><form method="post" action="/customers/contacts/update"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="customer_id" value="<?= (int)$customer['customer_id'] ?>"><input type="hidden" name="contact_id" value="<?= (int)$contact['contact_id'] ?>"><label>Type<select name="contact_type"><option value="phone"<?= $contact['contact_type']==='phone'?' selected':'' ?>>Phone</option><option value="email"<?= $contact['contact_type']==='email'?' selected':'' ?>>Email</option></select></label><label>New value<input name="contact_value" required maxlength="254"></label><label class="check-label"><input type="checkbox" name="is_primary" value="1"<?= $contact['is_primary']?' checked':'' ?>> Primary</label><button type="submit">Save contact</button></form></details><form method="post" action="/customers/contacts/remove" data-confirm="Remove this contact from the active profile?"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="customer_id" value="<?= (int)$customer['customer_id'] ?>"><input type="hidden" name="contact_id" value="<?= (int)$contact['contact_id'] ?>"><button class="button-danger button-small" type="submit">Remove</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$contacts):?><tr><td colspan="4">No contact channels recorded.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><h2>Identity documents</h2><p>Encrypted at rest. Document numbers are masked by default.</p></div><?php if($customer['deleted_at']===null):?><form class="form-grid" method="post" action="/customers/documents/add"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="customer_id" value="<?= (int)$customer['customer_id'] ?>"><label>Document type<select name="document_type" required><?php foreach($documentTypes as $type):?><option value="<?= $e($type) ?>"><?= $e(str_replace('_',' ',$type)) ?></option><?php endforeach;?></select></label><label>Document number<input name="document_number" required maxlength="100" autocomplete="off"></label><label>Expiry date<input type="date" name="expires_on"></label><button type="submit">Add document</button></form><?php endif;?><div class="table-wrap"><table><thead><tr><th>Type</th><th>Number</th><th>Expiry</th><th>Correct entry</th></tr></thead><tbody><?php foreach($documents as $document):?><tr><td><?= $e($document['document_type']) ?></td><td><span data-pii-value><?= $e($document['masked_value']) ?></span> <button type="button" class="button-small" data-reveal-kind="document" data-record-id="<?= (int)$document['document_id'] ?>">Reveal</button></td><td><?= $e($document['expires_on']??'—') ?></td><td><?php if($customer['deleted_at']===null):?><details><summary>Correct</summary><form method="post" action="/customers/documents/update"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="customer_id" value="<?= (int)$customer['customer_id'] ?>"><input type="hidden" name="document_id" value="<?= (int)$document['document_id'] ?>"><label>Document type<select name="document_type" required><?php foreach($documentTypes as $type):?><option value="<?= $e($type) ?>"<?= $document['document_type']===$type?' selected':'' ?>><?= $e(str_replace('_',' ',$type)) ?></option><?php endforeach;?></select></label><label>Correct document number<input name="document_number" required maxlength="100" autocomplete="off"></label><label>Expiry date<input type="date" name="expires_on" value="<?= $e($document['expires_on']??'') ?>"></label><button type="submit">Save correction</button></form></details><?php endif;?></td></tr><?php endforeach;?><?php if(!$documents):?><tr><td colspan="4">No identity documents recorded.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><h2>Identity document audit history</h2><p>Fingerprints only; document values are never written to this audit log.</p></div><div class="table-wrap"><table><thead><tr><th>When (UTC)</th><th>Operation</th><th>Type</th><th>Previous fingerprint</th><th>New fingerprint</th><th>Actor</th></tr></thead><tbody><?php foreach($documentAudits as $audit):?><tr><td><?= $e($audit['created_at']) ?></td><td><?= $e($audit['operation']) ?></td><td><?= $e($audit['document_type']) ?></td><td><?= $e($audit['old_fingerprint']??'—') ?></td><td><?= $e($audit['new_fingerprint']) ?></td><td><?= $e($audit['actor_email']) ?></td></tr><?php endforeach;?><?php if(!$documentAudits):?><tr><td colspan="6">No identity document changes recorded.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><h2>Staff notes</h2></div><?php if($customer['deleted_at']===null):?><form class="panel-body" method="post" action="/customers/notes/add"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="customer_id" value="<?= (int)$customer['customer_id'] ?>"><label>New note<textarea name="note_text" rows="3" maxlength="10000" required></textarea></label><button type="submit">Append note</button></form><?php endif;?><div class="table-wrap"><table><thead><tr><th>When (UTC)</th><th>Type</th><th>Note</th><th>By</th></tr></thead><tbody><?php foreach($notes as $note):?><tr><td><?= $e($note['created_at']) ?></td><td><?= $e($note['note_type']) ?></td><td><?= nl2br($e($note['note_text'])) ?></td><td><?= $e($note['author_email']) ?></td></tr><?php endforeach;?><?php if(!$notes):?><tr><td colspan="4">No notes recorded.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><h2>Rental history</h2></div><div class="table-wrap"><table><thead><tr><th>Agreement</th><th>Status</th><th>Start</th><th>End</th></tr></thead><tbody><?php foreach($rentals as $rental):?><tr><td>#<?= (int)$rental['agreement_id'] ?></td><td><?= $e($rental['status']) ?></td><td><?= $e($rental['start_date']) ?></td><td><?= $e($rental['end_date']) ?></td></tr><?php endforeach;?><?php if(!$rentals):?><tr><td colspan="4">No rental agreements recorded.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel customer-actions"><div class="panel-heading"><h2>Customer status</h2></div><div class="panel-body"><?php if($customer['deleted_at']!==null):?><p>Soft-deleted <?= $e($customer['deleted_at']) ?>. Historical records remain.</p><?php elseif((int)$customer['is_blacklisted']===1):?><p><strong>Blacklisted:</strong> <?= $e($customer['blacklist_reason']) ?> <small>since <?= $e($customer['blacklisted_at']) ?></small></p><form method="post" action="/customers/unblacklist"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="customer_id" value="<?= (int)$customer['customer_id'] ?>"><label>Reason for removing blacklist<textarea name="reason" maxlength="500" required></textarea></label><button type="submit">Unblacklist</button></form><?php else:?><form method="post" action="/customers/blacklist"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="customer_id" value="<?= (int)$customer['customer_id'] ?>"><label>Blacklist reason<textarea name="reason" maxlength="500" required></textarea></label><button class="button-danger" type="submit">Blacklist customer</button><p class="muted">Blacklisting blocks future bookings; existing rentals remain valid.</p></form><?php endif;?>
<?php if($customer['deleted_at']===null):?><form method="post" action="/customers/delete" data-confirm="Soft-delete this customer? Open agreements will block this action."><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="customer_id" value="<?= (int)$customer['customer_id'] ?>"><button class="button-danger" type="submit">Soft-delete customer</button></form><?php endif;?></div></section></main></body></html>
